"""CRUD endpoints for posts."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Post
from app.schemas import PostCreate, PostRead, PostUpdate

router = APIRouter(prefix="/posts", tags=["posts"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, post_id: int) -> Post:
    post = session.get(Post, post_id)
    if post is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Post not found")
    return post


@router.get("", response_model=list[PostRead])
def list_posts(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Post]:
    query = select(Post).order_by(Post.id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=PostRead, status_code=status.HTTP_201_CREATED)
def create_post(payload: PostCreate, session: SessionDep) -> Post:
    post = Post(**payload.model_dump())
    session.add(post)
    session.commit()
    session.refresh(post)
    return post


@router.get("/{post_id}", response_model=PostRead)
def get_post(post_id: int, session: SessionDep) -> Post:
    return _get_or_404(session, post_id)


@router.patch("/{post_id}", response_model=PostRead)
def update_post(
    post_id: int,
    payload: PostUpdate,
    session: SessionDep,
) -> Post:
    post = _get_or_404(session, post_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(post, key, value)
    session.commit()
    session.refresh(post)
    return post


@router.delete("/{post_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_post(post_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, post_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

"""CRUD endpoints for comments."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Comment, Post
from app.schemas import CommentCreate, CommentRead, CommentUpdate

router = APIRouter(prefix="/comments", tags=["comments"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, comment_id: int) -> Comment:
    comment = session.get(Comment, comment_id)
    if comment is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Comment not found")
    return comment


def _check_parents(
    session: Session,
    post_id: int | None,
) -> None:
    """A comment must point at a post that exist."""
    if post_id is not None and session.get(Post, post_id) is None:
        raise HTTPException(422, detail=f"Post {post_id} not found")


@router.get("", response_model=list[CommentRead])
def list_comments(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
    post_id: Annotated[int | None, Query(gt=0)] = None,
) -> list[Comment]:
    query = select(Comment).order_by(Comment.id)
    if post_id is not None:
        query = query.where(Comment.post_id == post_id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=CommentRead, status_code=status.HTTP_201_CREATED)
def create_comment(payload: CommentCreate, session: SessionDep) -> Comment:
    _check_parents(session, payload.post_id)
    comment = Comment(**payload.model_dump())
    session.add(comment)
    session.commit()
    session.refresh(comment)
    return comment


@router.get("/{comment_id}", response_model=CommentRead)
def get_comment(comment_id: int, session: SessionDep) -> Comment:
    return _get_or_404(session, comment_id)


@router.patch("/{comment_id}", response_model=CommentRead)
def update_comment(
    comment_id: int,
    payload: CommentUpdate,
    session: SessionDep,
) -> Comment:
    comment = _get_or_404(session, comment_id)
    _check_parents(session, payload.post_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(comment, key, value)
    session.commit()
    session.refresh(comment)
    return comment


@router.delete("/{comment_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_comment(comment_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, comment_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name prefix for every resource"
  type        = string
  default     = "posts-service"
}

variable "image_tag" {
  description = "Immutable image tag in the ECR repository to run (e.g. a git SHA)"
  type        = string
}

variable "vpc_id" {
  description = "VPC the service runs in"
  type        = string
}

variable "subnet_ids" {
  description = "Private subnets for the Fargate tasks"
  type        = list(string)
}

variable "container_port" {
  description = "Port the container listens on"
  type        = number
  default     = 8000
}

variable "desired_count" {
  description = "Number of running tasks"
  type        = number
  default     = 2
}

variable "database_url_secret_arn" {
  description = "Optional Secrets Manager ARN holding DATABASE_URL"
  type        = string
  default     = ""
}

locals {
  secrets = var.database_url_secret_arn == "" ? [] : [
    { name = "DATABASE_URL", valueFrom = var.database_url_secret_arn }
  ]
}

resource "aws_ecr_repository" "app" {
  name                 = var.name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/${var.name}"
  retention_in_days = 30
}

resource "aws_ecs_cluster" "this" {
  name = var.name

  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

data "aws_iam_policy_document" "ecs_tasks_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "execution" {
  name               = "${var.name}-execution"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json
}

resource "aws_iam_role_policy_attachment" "execution" {
  role       = aws_iam_role.execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_security_group" "service" {
  name        = "${var.name}-service"
  description = "Ingress to the ${var.name} tasks"
  vpc_id      = var.vpc_id

  ingress {
    description = "HTTP from inside the VPC"
    from_port   = var.container_port
    to_port     = var.container_port
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }

  egress {
    description = "Outbound HTTPS and database traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = var.name
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.execution.arn

  container_definitions = jsonencode([
    {
      name         = "api"
      image        = "${aws_ecr_repository.app.repository_url}:${var.image_tag}"
      essential    = true
      portMappings = [{ containerPort = var.container_port, protocol = "tcp" }]
      secrets      = local.secrets
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.app.name
          awslogs-region        = var.region
          awslogs-stream-prefix = "api"
        }
      }
    }
  ])
}

resource "aws_ecs_service" "app" {
  name            = var.name
  cluster         = aws_ecs_cluster.this.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = var.subnet_ids
    security_groups  = [aws_security_group.service.id]
    assign_public_ip = false
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }
}

output "ecr_repository_url" {
  description = "Push the image here"
  value       = aws_ecr_repository.app.repository_url
}

output "ecs_service_name" {
  description = "Name of the ECS service"
  value       = aws_ecs_service.app.name
}
